def lis_length(nums):
    """
    Returns the length of the longest strictly increasing subsequence.

    Args:
        nums (list[int]): List of integers.

    Returns:
        int: Length of the LIS.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] stores the length of LIS ending at index i

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
```

